ACPI_STATUS AcpiPsCompleteOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;
    ACPI_PARSE_OBJECT *NextOp;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->ParseOp == Op) {
        WalkState->ParseOp = NULL;
    }

    if (WalkState->ScopeInfo) {
        PrevOp = WalkState->ScopeInfo->PrevOp;
        if (PrevOp == Op) {
            WalkState->ScopeInfo->PrevOp = NULL;
        }
    }

    if (WalkState->Control.MethodCallCount > 0) {
        WalkState->Control.MethodCallCount--;
    }

    if (WalkState->Control.AscendingCallback) {
        Status = WalkState->Control.AscendingCallback(WalkState, Op, Status);
    }

    if (Status == AE_CTRL_PENDING) {
        return (AE_CTRL_TRANSFERRED);
    }

    if (WalkState->Control.AscendingCallback) {
        WalkState->Control.AscendingCallback = NULL;
    }

    if (WalkState->Control.ParamCount > 0) {
        WalkState->Control.ParamCount--;
    }

    if (WalkState->Control.ResultObj) {
        AcpiUtRemoveReference(WalkState->Control.ResultObj);
        WalkState->Control.ResultObj = NULL;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *ParentOp;
    ACPI_PARSE_OBJECT *NextOp;
    ACPI_STATUS Status2;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    /* Check if this is a deferred operation */
    if (Op->Common.Value.ArgList) {
        Status2 = AcpiPsCompleteDeferredOp(WalkState, Op);
        if (Status2 != AE_OK) {
            return (Status2);
        }
    }

    ParentOp = Op->Common.Parent;
    NextOp = Op->Common.Next;

    if (ParentOp) {
        if (ParentOp->Common.Type == AML_PACKAGE_OP) {
            if (!ParentOp->Common.Value.Arg) {
                ParentOp->Common.Value.Arg = Op;
            } else {
                Status2 = AcpiPsCompleteFinalOp(WalkState, ParentOp, Status);
                if (Status2 != AE_OK) {
                    return (Status2);
                }
            }
        }
    }

    if (NextOp) {
        if (NextOp->Common.Type == AML_NAMESTRING_OP) {
            Status2 = AcpiPsCompleteFinalOp(WalkState, NextOp, Status);
            if (Status2 != AE_OK) {
                return (Status2);
            }
        }
    }

    if (Op->Common.Callback) {
        Status2 = Op->Common.Callback(WalkState, Op, Status);
        if (Status2 != AE_OK) {
            return (Status2);
        }
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *ParentOp;
    ACPI_PARSE_OBJECT *PrevOp;
    ACPI_PARSE_OBJECT *LastOp;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->OpList) {
        LastOp = WalkState->OpList;
    } else {
        LastOp = Op;
    }

    do {
        if (LastOp != Op) {
            ParentOp = AcpiPsGetParentOp(LastOp);
            PrevOp = LastOp->Common.Next;
        } else {
            ParentOp = WalkState->RootNode;
            PrevOp = NULL;
        }

        if (WalkState->DescBase.NextOp) {
            if (LastOp == WalkState->DescBase.NextOp) {
                WalkState->DescBase.NextOp = PrevOp;
            }
        }

        if (WalkState->Control.Method) {
            if (LastOp->Common.Value.Obj == WalkState->Control.Method) {
                WalkState->Control.Method = NULL;
            }
        }

        if (WalkState->Control.NextOp == LastOp) {
            WalkState->Control.NextOp = PrevOp;
        }

        if (WalkState->Results.Value) {
            if (WalkState->Results.Value == LastOp) {
                WalkState->Results.Value = NULL;
            }
        }

        if (WalkState->OpList == LastOp) {
            WalkState->OpList = PrevOp;
        }

        if (WalkState->ParserState.Scope.Obj == LastOp) {
            WalkState->ParserState.Scope.Obj = NULL;
        }

        if (WalkState->ParserState.Scope.Next) {
            WalkState->ParserState.Scope.Next = NULL;
        }

        if (LastOp->Common.Value.Obj) {
            (void)AcpiUtRemoveReference(LastOp->Common.Value.Obj);
        }

        if (LastOp->Named.Next) {
            (void)AcpiUtRemoveReference(LastOp->Named.Next);
        }

        (void)AcpiUtRemoveReference(LastOp);

        LastOp = PrevOp;
    } while (LastOp);

    return (Status);
}

ACPI_STATUS AcpiPsCompleteParsing(
    ACPI_WALK_STATE *WalkState,
    ACPI_PARSE_OBJECT *Op,
    ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *Next;
    ACPI_PARSE_OBJECT *NextOp;
    ACPI_PARSE_OBJECT *NextNext;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    do
    {
        if (Status != AE_CTRL_PENDING)
        {
            if (WalkState->ParserState.ScopeDepth > 0)
            {
                WalkState->ParserState.ScopeDepth--;
            }
        }

        if (WalkState->ControlState)
        {
            AcpiUtPopControlState(WalkState);
        }

        if (WalkState->Result)
        {
            AcpiUtRemoveReference(WalkState->Result);
            WalkState->Result = NULL;
        }

        if (WalkState->MethodNode)
        {
            WalkState->MethodNode = NULL;
        }

        if (WalkState->WalkList.NextWalk)
        {
            WalkState = WalkState->WalkList.NextWalk;
        }

    } while (WalkState && WalkState->ParserState.ScopeDepth > 0);

    return (Status);
}

ACPI_STATUS AcpiPsCompleteOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->ControlState)
    {
        if (WalkState->ControlState->Common.Value == ACPIPs_PUSH_CONTROL)
        {
            if (Status == AE_CTRL_TRANSFER)
            {
                WalkState->ControlState = WalkState->ControlState->Next;
                return (AE_OK);
            }
        }
        else if (WalkState->ControlState->Common.Value == ACPIPs_PUSH_ARG_LIST)
        {
            if (Status == AE_CTRL_TRANSFER)
            {
                WalkState->ControlState = WalkState->ControlState->Next;
                return (AE_OK);
            }
        }
        else if (WalkState->ControlState->Common.Value == ACPIPs_PUSH_NAMEPATH)
        {
            if (Status == AE_CTRL_TRANSFER)
            {
                WalkState->ControlState = WalkState->ControlState->Next;
                return (AE_OK);
            }
        }
    }

    PrevOp = Op->Common.Next;
    if (PrevOp)
    {
        if (PrevOp->Common.Type == AML_SCOPE_OP)
        {
            if (WalkState->ScopeInfo->Prev)
            {
                WalkState->ScopeInfo = WalkState->ScopeInfo->Prev;
            }
        }
    }

    if (Op->Common.Value.Obj)
    {
        AcpiUtRemoveReference(Op->Common.Value.Obj);
    }

    if (WalkState->ParserState.NextOp == Op)
    {
        WalkState->ParserState.NextOp = PrevOp;
    }

    if (WalkState->ParserState.AstRoot == Op)
    {
        WalkState->ParserState.AstRoot = NULL;
    }

    if (WalkState->Results && WalkState->Results->NumResults > 0)
    {
        WalkState->Results->NumResults--;
    }

    if (WalkState->ControlState)
    {
        WalkState->ControlState->Common.Value = ACPIPs_POP_CONTROL;
        WalkState->ControlState->Common.Value = ACPIPs_POP_ARG_LIST;
        WalkState->ControlState->Common.Value = ACPIPs_POP_NAMEPATH;
    }

    return (Status);
}
